import * as T from './vendor/three.module.js';
import {ANIMAL_MOTION_CATALOG} from './animal-motion-catalog.js';
import {createAnimalPaint} from './animal-motion-paint.js';
import {createWorkerLocomotion} from './worker-locomotion.js';
import {createWeaponModel} from './weapon-models.js';
const $=id=>document.getElementById(id),profile=ANIMAL_MOTION_CATALOG.find(p=>p.id==='donkey');
const renderer=new T.WebGLRenderer({canvas:$('scene'),antialias:true,preserveDrawingBuffer:true});renderer.setPixelRatio(Math.min(devicePixelRatio,2));renderer.setClearColor('#d6d3bb');renderer.shadowMap.enabled=true;
const scene=new T.Scene(),camera=new T.OrthographicCamera(),loader=new T.TextureLoader();scene.add(new T.HemisphereLight(0xfff1dc,0x657c86,2));const sun=new T.DirectionalLight(0xfff0d6,2.5);sun.position.set(3,5,4);sun.castShadow=true;scene.add(sun);const ground=new T.Mesh(new T.PlaneGeometry(200,200),new T.MeshStandardMaterial({color:0xb4b29b,roughness:1}));ground.rotation.x=-Math.PI/2;ground.receiveShadow=true;scene.add(ground);
const worker=profile.create(await(await fetch(profile.file)).json()),hands=createWeaponModel('hands');worker.equipWeapon(hands);scene.add(worker.root);const locomotion=createWorkerLocomotion(worker,profile);let paint,loading=false,request=0,elapsed=0,last=performance.now();
async function outfit(){if(loading)return;loading=true;try{const next=await createAnimalPaint(renderer,worker,profile,loader,$('outfit').value,true);paint?.dispose();paint=next;worker.parts.forEach(p=>{p.material=paint.material;p.castShadow=p.receiveShadow=true;});window.donkeyGuide.ready=true;}finally{loading=false;}}
function render(){const w=$('scene').clientWidth,h=$('scene').clientHeight;renderer.setSize(w,h,false);const height=2.3;camera.left=-height*w/h/2;camera.right=-camera.left;camera.top=height/2;camera.bottom=-height/2;camera.near=.01;camera.far=100;const direction={three:[4,1.5,5],front:[6,1,0],side:[0,1,6],back:[-6,1,0]}[$('view').value];camera.position.set(...direction).add(new T.Vector3(0,.9,0));camera.lookAt(0,.9,0);camera.updateProjectionMatrix();locomotion.apply({weapon:'hands',heading:0,distance:elapsed*1.3,blend:$('walk').checked?1:0,pose:{}});worker.root.updateMatrixWorld(true);worker.skeleton.update();renderer.render(scene,camera);}
window.donkeyGuide={ready:false,worker,render};$('outfit').onchange=outfit;await outfit();function tick(now){elapsed+=Math.min(.05,(now-last)/1000);last=now;render();request=requestAnimationFrame(tick);}request=requestAnimationFrame(tick);addEventListener('pagehide',()=>{cancelAnimationFrame(request);locomotion.dispose();paint?.dispose();hands.dispose();worker.dispose();ground.geometry.dispose();ground.material.dispose();renderer.dispose();},{once:true});
